import { Table, StringColumn, GenericColumn } from '../../db'

export const sys_auth_profile = Table({
    name: 'sys_auth_profile',
    extends: 'sys_metadata',
    schema: {
        name: StringColumn({
            mandatory: false,
            label: 'Name',
            read_only: false,
            active: true,
            maxLength: 40,
            dropdown: 'none',
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
    },
})
